INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7680118, 1256358, 6804, '<td valign="top">A lovely "High Key" portraiture!   The contrast may not be as extreme as the voters might be wanting to see, which may cost you some votes.  The presentation is just too good to not score it well.  High marks from me.  It''s beautiful work.</td>', 'A lovely "High Key" portraiture!   The contrast may not be as extreme as the voters might be wanting to see, which may cost you some votes.  The presentation is just too good to not score it well.  High marks from me.  It''s beautiful work.', '2020-11-25 00:57:54.000000', NULL, 1),
(7680119, 1256314, 6804, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2020-11-25 01:00:58.000000', NULL, 1),
(7680120, 1256316, 6804, '<td valign="top">This is perfect in every way!  Excellent pick and processing for "High Contrast"</td>', 'This is perfect in every way!  Excellent pick and processing for "High Contrast"', '2020-11-25 01:04:13.000000', NULL, 1),
(7680121, 1256522, 6804, '<td valign="top">Excellent!  This is beautiful work and it checks almost all the boxes with strong interest and quality; It''s a creative angle, great perspective, clear depth of field through the entire distance.  Really nice work.  If I had only one item to improve on this,  it would be to simply let the highlights almost blow-out.  Your shadows and mid-tones are simply perfect.  I think you may have softened some harshness and pulled back on your highlights, which still makes a stellar image just the way it is.  It just cost you a little "contrast" is all.   Very high marks from me.</td>', 'Excellent!  This is beautiful work and it checks almost all the boxes with strong interest and quality; It''s a creative angle, great perspective, clear depth of field through the entire distance.  Really nice work.  If I had only one item to improve on this,  it would be to simply let the highlights almost blow-out.  Your shadows and mid-tones are simply perfect.  I think you may have softened some harshness and pulled back on your highlights, which still makes a stellar image just the way it is.  It just cost you a little "contrast" is all.   Very high marks from me.', '2020-11-25 01:21:07.000000', NULL, 1),
(7680122, 1256477, 6804, '<td valign="top">A very fun image!  (Love the title).</td>', 'A very fun image!  (Love the title).', '2020-11-25 01:25:37.000000', NULL, 1),
(7680123, 1256411, 6804, '<td valign="top">This is a wonderful piece of art!  Excellent subject and processing for a "High Contrast" presentation.  High marks from me.</td>', 'This is a wonderful piece of art!  Excellent subject and processing for a "High Contrast" presentation.  High marks from me.', '2020-11-25 01:34:54.000000', NULL, 1),
(7680124, 1256331, 6804, '<td valign="top">Beautiful work!</td>', 'Beautiful work!', '2020-11-25 01:35:27.000000', NULL, 1),
(7680129, 1256566, 6804, '<td valign="top">Wow!  Perfect.   I really don''t think this should be changed in any way.</td>', 'Wow!  Perfect.   I really don''t think this should be changed in any way.', '2020-11-25 01:40:05.000000', NULL, 1),
(7680130, 1256526, 6804, '<td valign="top">I love this!  You''ve created a genuine work of art from a mundane pile of wood.  Excellent work.  a solid 10 from me.</td>', 'I love this!  You''ve created a genuine work of art from a mundane pile of wood.  Excellent work.  a solid 10 from me.', '2020-11-25 01:54:20.000000', NULL, 1),
