(7680187, 1256174, 114285, '<td valign="top">You sure this is not the same image <a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1191935" rel="nofollow" target="_blank"><img border="0" src="//images.dpchallenge.com/images_challenge/2000-2999/2399/120/Copyrighted_Image_Reuse_Prohibited_1191935.jpg" xalt="'' . substr(''//images.dpchallenge.com/images_challenge/2000-2999/2399/120/Copyrighted_Image_Reuse_Prohibited_1191935.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/2000-2999/2399/120/Copyrighted_Image_Reuse_Prohibited_1191935.jpg'', ''/'') + 1) . ''"/></a> <br/>Being on the SC I''m sure you wouldn''t make that mistake ;)<br/> <br/>BTW I only found it by chance due to looking at past tree entries.</td>', 'You sure this is not the same image  Being on the SC I''m sure you wouldn''t make that mistake ;) BTW I only found it by chance due to looking at past tree entries.', '2020-11-26 03:20:49.000000', NULL, 1),
(7680200, 1256181, 4008, '<td valign="top">I don''t consider this to be high contrast. The image contains no blacks or near-black tones, hardly any highlights (or near white) and a lot of midtones, quite evenly distributed. Have a look at the histogram.</td>', 'I don''t consider this to be high contrast. The image contains no blacks or near-black tones, hardly any highlights (or near white) and a lot of midtones, quite evenly distributed. Have a look at the histogram.', '2020-11-26 04:46:49.000000', NULL, 1),
(7680201, 1256477, 4008, '<td valign="top">It does have some black and whites, but predominantly a full nice range of midtones.  To me this is not high contrast.</td>', 'It does have some black and whites, but predominantly a full nice range of midtones.  To me this is not high contrast.', '2020-11-26 04:49:31.000000', NULL, 1),
(7680202, 1256226, 4008, '<td valign="top">Looking at the histogrram I see a lot of blacks and then some midtones up halfway. Hardly any lighter midtones and highlights. Not high contrast to me.<br/>But a nice image nevertheless.</td>', 'Looking at the histogrram I see a lot of blacks and then some midtones up halfway. Hardly any lighter midtones and highlights. Not high contrast to me.But a nice image nevertheless.', '2020-11-26 04:53:22.000000', NULL, 1),
(7680203, 1256411, 4008, '<td valign="top">Yes, high contrast, but a lot of details (too much) are lost.</td>', 'Yes, high contrast, but a lot of details (too much) are lost.', '2020-11-26 04:54:22.000000', NULL, 1),
(7680204, 1256273, 4008, '<td valign="top">Yes, high contrast but too much detail lost in the birds.</td>', 'Yes, high contrast but too much detail lost in the birds.', '2020-11-26 04:55:34.000000', NULL, 1),
(7680205, 1256520, 4008, '<td valign="top">Hardly any blacks or near-blacks, hardly any highlights, a lot of midtones. Not high contrast to me.</td>', 'Hardly any blacks or near-blacks, hardly any highlights, a lot of midtones. Not high contrast to me.', '2020-11-26 04:56:32.000000', NULL, 1),
(7680206, 1256541, 4008, '<td valign="top">The eyes are extremely dark and the shadows or reflections in her eyes make her iris look misformed. It takes away from her beauty.</td>', 'The eyes are extremely dark and the shadows or reflections in her eyes make her iris look misformed. It takes away from her beauty.', '2020-11-26 05:02:50.000000', NULL, 1),
(7680207, 1256436, 4008, '<td valign="top">Very beautiful image but not so strong as a high-contrast image. Too many midtones, not enough extremes.</td>', 'Very beautiful image but not so strong as a high-contrast image. Too many midtones, not enough extremes.', '2020-11-26 05:04:49.000000', NULL, 1),
(7680208, 1256331, 4008, '<td valign="top">Yes, high contrast, but nearly all detail is lost.</td>', 'Yes, high contrast, but nearly all detail is lost.', '2020-11-26 05:05:29.000000', NULL, 1),
(7680209, 1256174, 4008, '<td valign="top">A very even distribution over the total tonal range, with the exception of the (near-)blacks. Not high contrast to me</td>', 'A very even distribution over the total tonal range, with the exception of the (near-)blacks. Not high contrast to me', '2020-11-26 05:06:56.000000', NULL, 1),
(7680210, 1256545, 4008, '<td valign="top">Predominantly midtones, no high contrast to me, especially missing dark/black tones.</td>', 'Predominantly midtones, no high contrast to me, especially missing dark/black tones.', '2020-11-26 05:10:34.000000', NULL, 1),
(7680211, 1256562, 4008, '<td valign="top">Great patterns and nice high contrast. I suggest to crop away the top 10%, i.e. to remove the two white parts of the top left balconies. They seem to break the pattern.</td>', 'Great patterns and nice high contrast. I suggest to crop away the top 10%, i.e. to remove the two white parts of the top left balconies. They seem to break the pattern.', '2020-11-26 05:17:04.000000', NULL, 1),
(7680212, 1256401, 4008, '<td valign="top">Nice image, but no blacks or whites and quite an even distribution of midtones. Not high contrast to me.</td>', 'Nice image, but no blacks or whites and quite an even distribution of midtones. Not high contrast to me.', '2020-11-26 05:21:18.000000', NULL, 1),
(7680213, 1256566, 4008, '<td valign="top">Very nice high contrast, with details still preserved.</td>', 'Very nice high contrast, with details still preserved.', '2020-11-26 05:21:57.000000', NULL, 1),
(7680214, 1256358, 4008, '<td valign="top">Very nice portrait, but with a good distribution of across the tonal range, skewed towards highlights, hardly any real blacks or dark tones.</td>', 'Very nice portrait, but with a good distribution of across the tonal range, skewed towards highlights, hardly any real blacks or dark tones.', '2020-11-26 05:25:47.000000', NULL, 1),
(7680215, 1256182, 4008, '<td valign="top">Really nice image, but predominantly midtones, hardly any blacks or whites, not high contrast to me.</td>', 'Really nice image, but predominantly midtones, hardly any blacks or whites, not high contrast to me.', '2020-11-26 05:27:43.000000', NULL, 1),
(7680216, 1256432, 4008, '<td valign="top">Too much detail lost.</td>', 'Too much detail lost.', '2020-11-26 05:27:56.000000', NULL, 1),
(7680217, 1256552, 4008, '<td valign="top">Nice portrait. Good contrast with most pixels being at both sides of the histogram. The highlights could have been moved a bit further.</td>', 'Nice portrait. Good contrast with most pixels being at both sides of the histogram. The highlights could have been moved a bit further.', '2020-11-26 05:33:57.000000', NULL, 1),
(7680218, 1256452, 4008, '<td valign="top">Good contrast. I like the action caused by the spray of water.</td>', 'Good contrast. I like the action caused by the spray of water.', '2020-11-26 05:34:50.000000', NULL, 1),
(7680219, 1256565, 4008, '<td valign="top">Great atmosphere in this image. Great composition. Details are lost in the highlights but in this image those details don''t matter, so not a problem.</td>', 'Great atmosphere in this image. Great composition. Details are lost in the highlights but in this image those details don''t matter, so not a problem.', '2020-11-26 05:36:47.000000', NULL, 1),
(7680220, 1256576, 4008, '<td valign="top">My top pick in this challenge. Really high contrast, nice scene and expression. The light vertical lines really add to the composition.  Still just enough detail in the face.</td>', 'My top pick in this challenge. Really high contrast, nice scene and expression. The light vertical lines really add to the composition.  Still just enough detail in the face.', '2020-11-26 05:39:09.000000', NULL, 1),
(7680221, 1256580, 4008, '<td valign="top">I like the different colors in the image. Converting it to black and white would take the atmosphere away, although I would tone down the tree on the right a bit.</td>', 'I like the different colors in the image. Converting it to black and white would take the atmosphere away, although I would tone down the tree on the right a bit.', '2020-11-26 05:43:24.000000', NULL, 1),
(7680222, 1256543, 4008, '<td valign="top">Intriguing image, draws in the attention.</td>', 'Intriguing image, draws in the attention.', '2020-11-26 05:45:05.000000', NULL, 1),
(7680223, 1256453, 4008, '<td valign="top">A pity you are limited to 1200 pixels wide, this would look so much better at large format. Very nice scene.</td>', 'A pity you are limited to 1200 pixels wide, this would look so much better at large format. Very nice scene.', '2020-11-26 05:46:16.000000', NULL, 1),
(7680224, 1256547, 4008, '<td valign="top">Yes, high contrast, but not a very interesting image to me.</td>', 'Yes, high contrast, but not a very interesting image to me.', '2020-11-26 05:50:06.000000', NULL, 1),
