(7680420, 1256306, 30049, '<td valign="top">Well done!</td>', 'Well done!', '2020-11-29 16:13:15.000000', NULL, 1),
(7680421, 1256566, 30049, '<td valign="top">Nice!  Just pushed it enough without losing the bird to the background.  Also doesn''t hurt that it''s a well timed capture.  :-)</td>', 'Nice!  Just pushed it enough without losing the bird to the background.  Also doesn''t hurt that it''s a well timed capture.  :-)', '2020-11-29 16:15:58.000000', NULL, 1),
